  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a limit on how many units can be purchased in any single month (a monthly purchase budget or cap), or can you buy any non-negative quantity at that month's purchase price?"
  ],
  "rationale": "The response asks a single clarification question regarding the existence of a monthly purchase cap versus unlimited purchasing."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any limit on how many units can be sold in a given month (such as a monthly demand cap), or can you sell any non-negative quantity up to whatever you have available to sell?"
  ],
  "rationale": "The response asks a single clarification question regarding the existence of a monthly sales cap versus unlimited sales up to availability."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When you say \"maximize total revenue,\" do you mean maximize total sales revenue (selling price times units sold) only, or maximize net profit (sales revenue minus the purchase cost of units bought)?"
  ],
  "rationale": "The response asks for a single policy choice between two definitions of the objective function."
}

{
  "action": "question",
