  "is_atomic": true,
  "atomic_questions": [
    "Can units purchased in a given month be sold in that same month, or must a unit be bought in one month and held in inventory before it can be sold in a later month?"
  ],
  "rationale": "The response asks for a single policy choice regarding the timing of sales relative to purchases, which constitutes one semantically independent question."
}

{
  "action": "question",
